            count++;
            if (count == k) return curr->data;
            curr = curr->right;
        }
        else {
            // Find inorder predecessor
            Node* prev = curr->left;
            while (prev->right != NULL && prev->right != curr) {
                prev = prev->right;
            }

            // Threading: make curr right child of its inorder predecessor
            if (prev->right == NULL) {
                prev->right = curr;
                curr = curr->left;
            }
            else {
                // Revert the threading
                prev->right = NULL;

                count++;
                if (count == k) return curr->data;

                curr = curr->right;
            }
        }
    }
    return -1;
}

